import data from "@/data/builder.json";
import { seats2023 } from "@/lib/seats-2023";
import { seats2026 } from "@/lib/seats-2026";
import type { BuilderReference } from "./allocate";
import type { CatalogParty, SeatTable } from "./types";

// Reference data of the builder, generated by `pnpm data:builder`.
export const censusElection = data.censusElection;
export const builderCensus: ReadonlyMap<string, number> = new Map(Object.entries(data.census));
export const catalog: readonly CatalogParty[] = data.parties;

export const seatTables = { "2023": seats2023, "2026": seats2026 } satisfies Record<SeatTable, ReadonlyMap<string, number>>;

export const builderReference: BuilderReference = {
  census: builderCensus,
  catalog: new Map(catalog.map((party) => [party.id, party])),
};
